        incl = excl + arr[i]
        excl = new_excl
    return max(incl, excl)

def max_char(s):
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    max_char = max(char_count, key=char_count.get)
    return max_char

def roman_to_int(roman):
    roman_dict = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result = 0
    for i in range(len(roman)):
        if i > 0 and roman_dict[roman[i]] > roman_dict[roman[i - 1]]:
            result += roman_dict[roman[i]] - 2 * roman_dict[roman[i - 1]]
        else:
            result += roman_dict[roman[i]]
    return result

def candidate(operations):
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def candidate(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def candidate(lst):
    max_val = float('-inf')
    for num in lst:
        if num > max_val:
            max_val = num
    return max_val

def candidate(x, base):
    result = []
    while x > 0:
        remainder = x % base
        result.append(str(remainder))
        x = x // base
    result.reverse()
    return ''.join(result)

def candidate(l):
    l.sort()
    n = len(l)
    if n % 2 == 1:
        return l[n // 2]
    else:
        return (l[n // 2 - 1] + l[n // 2]) / 2

def candidate(n):
    if n == 1 or n == 2:
        return 1
    else:
        return candidate(n - 1) + candidate(n - 2)
